// =============================================================
// Node: "Préparer envois RH"  (remplace Limit + ancien Prep J-0)
//
// Logique :
//   1. Grouper les prospects filtrés par domaine
//   2. Classer RH vs non-RH
//   3. RH dispo → 1 mail par RH en TO, managers/directors en CC
//   4. Pas de RH → 1er contact en TO, les autres en CC
//   5. Sortie : items prêts à envoyer (Limit 1 en aval)
// =============================================================

const items = $input.all();

// --- Détection RH ---
const RH_KW = [
  'rh','hr','drh','rrh',
  'ressources humaines','human resources',
  'recrutement','recruitment','recruiter',
  'talent acquisition','people operations',
  'mobilité','paie','adp','headhunter'
];
function isRH(titre) {
  const t = (titre || '').toLowerCase();
  return RH_KW.some(k => t.includes(k));
}

// --- Grouper par domaine ---
const byCompany = {};
for (const item of items) {
  const key = String(item.json.Domaine || 'unknown').trim().toLowerCase();
  (byCompany[key] ||= []).push(item.json);
}


const SIGNATURE = `<!-- votre bloc de signature ici -->
          </td>
          <td valign="middle" style="padding: 0 0 0 15px; background-color: #ffffff;">
            <img src="data:image/jpeg;base64,VOTRE_LOGO_EN_BASE64" width="140" height="61" alt="Certifié ISO 9001" style="display: block; border: 0; outline: none; background-color: #ffffff;">
          </td>
        </tr>
      </table>
      <!-- votre bloc de signature ici -->
      <!-- votre bloc de signature ici -->
    </td>
  </tr>
</table>`;
// ⚠️ IMPORTANT : Les base64 ci-dessus sont des placeholders.
// → Copie-colle le contenu EXACT de la variable SIGNATURE de ton ancien Prep J-0
//   pour retrouver les vraies images (logo acme, ISO 9001, avion).

// --- Générer le HTML du mail (identique à l'original) ---
function buildEmail(decideurFullName, entreprise) {
  const decideur = (decideurFullName || "").trim().split(/\s+/)[0] || "Madame, Monsieur";

  return `<!DOCTYPE html>
<html>
<head><meta charset="UTF-8"></head>
<body style="margin: 0; padding: 0; background-color: #ffffff; font-family: Arial, Helvetica, sans-serif;">
<div style="padding: 30px; max-width: 650px; font-family: Arial, Helvetica, sans-serif; font-size: 14px; color: #333333;">

<p style="margin: 0 0 20px 0; line-height: 1.7;">Bonjour ${decideur},</p>

<p style="margin: 0 0 20px 0; line-height: 1.7;">Je me permets de vous contacter dans le cadre du développement de notre réseau de partenaires.</p>

<p style="margin: 0 0 20px 0; line-height: 1.7;">Chez acme Intérim, nous avons construit notre activité autour de valeurs qui nous tiennent vraiment à cœur : la réactivité, la qualité, la proximité avec nos clients et un engagement durable dans la durée.</p>

<p style="margin: 0 0 20px 0; line-height: 1.7;">Notre ambition est simple. Nous voulons proposer un accompagnement fiable, avec des équipes choisies avec soin, un suivi réel sur le terrain et une vraie capacité à nous adapter aux contraintes opérationnelles, même dans les environnements les plus exigeants.</p>

<p style="margin: 0 0 20px 0; line-height: 1.7;">Dans cette logique, acme Intérim est certifiée ISO 9001. C'est une démarche qui traduit notre volonté d'offrir un niveau de qualité constant et une attention permanente à la satisfaction de nos clients.</p>

<p style="margin: 0 0 20px 0; line-height: 1.7;">Parce que les besoins opérationnels ne s'arrêtent pas aux horaires de bureau, nous assurons aussi une astreinte 24h/24 et 7j/7. Comme ça, vous pouvez compter sur nous à tout moment.</p>

<p style="margin: 0 0 20px 0; line-height: 1.7;">Plutôt que de continuer avec un long discours commercial, je préfère vous proposer un échange rapide pour mieux comprendre vos besoins et voir si une collaboration pourrait avoir du sens.</p>

<p style="margin: 0 0 20px 0; line-height: 1.7;">Je reste disponible pour un court échange téléphonique quand cela vous arrange.</p>

<p style="margin: 0 0 20px 0; line-height: 1.7;">Bien cordialement,</p>

${SIGNATURE}

</div>
</body>
</html>`;
}
// ===================== LOGIQUE PRINCIPALE =====================
const results = [];

for (const [company, prospects] of Object.entries(byCompany)) {
const rhContacts = prospects.filter(p => isRH(p.Post));
const nonRh      = prospects.filter(p => !isRH(p.Post));

  // Ordre de priorité : RH d'abord, puis les autres. On ne garde que ceux qui ont un email.
  const ordered = (rhContacts.length > 0 ? [...rhContacts, ...nonRh] : [...prospects])
                    .filter(p => p.Email);
  if (ordered.length === 0) continue;

  const main   = ordered[0];        // meilleur RH = destinataire principal
  const others = ordered.slice(1);  // tous les autres = en copie

  // CC = tous les autres contacts (RH restants + non-RH) + PRENOM
  const ccEmails = others.map(p => p.Email).filter(Boolean);
  const ccString = [...ccEmails, 'prenom.nom@exemple.fr'].join(', ');

  // Lignes à mettre à jour dans Excel, avec leur rôle
const contacts = [
  { ID_Prospect: main.ID_Prospect, Statut: 'Contacté' },
  ...others.map(p => ({ ID_Prospect: p.ID_Prospect, Statut: 'Copie' }))
];;

  results.push({
    json: {
      ...main,
      to: main.Email,
      cc: ccString,
       subject: `${main.Entreprise} — acme Interim, votre partenaire interim aeroportuaire`,
      html: buildEmail(main.Décideur, main.Entreprise),
      contacts,                                   // pour le nœud d'expansion ci-dessous
      _type: rhContacts.length > 0 ? 'rh' : 'fallback'
    }
  });
}

return results;

const item = $('Limit').first().json;
return (item.contacts || []).map(c => ({
  json: {
    ID_Prospect: c.ID_Prospect,
    Statut: c.Statut          // "Contacté" ou "Copie"
  }
}));

const item = $('Limit2').first().json;
return (item.contacts || []).map(c => ({
  json: {
    ID_Prospect: c.ID_Prospect,
    Statut: c.Statut === 'Copie' ? 'Copie' : 'Froid'
  }
}));

const rows = $input.all().map(it => it.json);
const PRENOM = 'prenom.nom@exemple.fr';

function parseDate(v) {
  if (v === '' || v == null) return null;
  if (typeof v === 'number' || /^\d+(\.\d+)?$/.test(String(v))) {
    return DateTime.fromObject({ year: 1899, month: 12, day: 30 }).plus({ days: Number(v) });
  }
  const d = DateTime.fromFormat(String(v), 'dd-MM-yyyy');
  return d.isValid ? d : null;
}

const byCompany = {};
for (const p of rows) {
  const key = String(p.Domaine || 'unknown').trim().toLowerCase();
  (byCompany[key] ||= []).push(p);
}

const results = [];
const limite = $now.minus({ days: 10 }).startOf('day');  // 10 jours après la 1ère relance


for (const [company, group] of Object.entries(byCompany)) {
  if (group.some(r => r.Action === 'Stop' || r.Statut === 'Stop')) continue;

 const main = group.find(r => r.Statut === 'Relance J7');   // au lieu de 'Relance J5'
  if (!main || !main.Email) continue;
  if (main.Email_Statut === '❌ Mauvais') continue;

  // ⬅️ échéance basée sur Date_J0 (et non plus Date_J5)
const dJ7 = parseDate(main.Date_J7);
if (!dJ7 || dJ7 > limite) continue;

  if (main.Date_J17) continue;

  const copies = group.filter(r => r.Statut === 'Copie');
  const cc = [...copies.map(r => r.Email).filter(Boolean), PRENOM].join(', ');

  const contacts = [
    { ID_Prospect: main.ID_Prospect, Statut: 'Relance J12' },
    ...copies.map(r => ({ ID_Prospect: r.ID_Prospect, Statut: 'Copie' }))
  ];

  results.push({ json: { ...main, to: main.Email, cc, contacts } });
}

return results;

const item = $('Limit1').first().json;
return (item.contacts || []).map(c => ({
  json: { ID_Prospect: c.ID_Prospect, Statut: c.Statut }
}));

const rows = $input.all().map(it => it.json);
const PRENOM = 'prenom.nom@exemple.fr';

function parseDate(v) {
  if (v === '' || v == null) return null;
  if (typeof v === 'number' || /^\d+(\.\d+)?$/.test(String(v))) {
    return DateTime.fromObject({ year: 1899, month: 12, day: 30 }).plus({ days: Number(v) });
  }
  const d = DateTime.fromFormat(String(v), 'dd-MM-yyyy');
  return d.isValid ? d : null;
}

const byCompany = {};
for (const p of rows) {
  const key = String(p.Domaine || 'unknown').trim().toLowerCase();
  (byCompany[key] ||= []).push(p);
}

const results = [];
const limite = $now.minus({ days: 7 }).startOf('day');   // 7 jours après Date_J0

for (const [company, group] of Object.entries(byCompany)) {
  // Stop propagé : une ligne en Stop -> toute l'entreprise est exclue
  if (group.some(r => r.Action === 'Stop' || r.Statut === 'Stop')) continue;

  const main = group.find(r => r.Statut === 'Contacté');
  if (!main || !main.Email) continue;
  if (main.Email_Statut === '❌ Mauvais') continue;

  // Échéance : 5 jours après Date_J0
  const dJ0 = parseDate(main.Date_J0);
  if (!dJ0 || dJ0 > limite) continue;

  // Pas de 1ère relance si déjà faite
  if (main.Date_J7) continue;

  const copies = group.filter(r => r.Statut === 'Copie');
  const cc = [...copies.map(r => r.Email).filter(Boolean), PRENOM].join(', ');

const contacts = [
  { ID_Prospect: main.ID_Prospect, Statut: 'Relance J7' },
  ...copies.map(r => ({ ID_Prospect: r.ID_Prospect, Statut: 'Copie' }))
];
  results.push({ json: { ...main, to: main.Email, cc, contacts } });
}

return results;
